const p = $json.body || $json;
const d = p.data || {};
const lines = [
  `HydraMind: ${p.event}`,
  d.target ? `Target: ${d.target}` : null,
  d.scan_id ? `Scan: #${d.scan_id}` : null,
  d.profile ? `Profile: ${d.profile}` : null,
  d.verdicts && Object.keys(d.verdicts).length ? `Verdicts: ${Object.entries(d.verdicts).map(([k, v]) => `${k}=${v}`).join(', ')}` : null,
  d.reason ? `Reason: ${d.reason}` : null,
].filter(Boolean);
return [{ json: { event: p.event, message: lines.join('\n'), payload: p } }];
